  "(juu ya ruhusa zako)": { sw: "(juu ya ruhusa zako)", en: "(on top of your permissions)" },
  "Herufi ndogo/namba, 3–32, bila nafasi. Jina ni la kipekee kwa biashara zote (mfano asha.duka1). Biashara moja inaweza kuwa na admin na watumiaji wengi wa role moja, kila mmoja akiwa na username yake.": { sw: "Herufi ndogo/namba, 3–32, bila nafasi. Jina ni la kipekee kwa biashara zote (mfano asha.duka1). Biashara moja inaweza kuwa na admin na watumiaji wengi wa role moja, kila mmoja akiwa na username yake.", en: "Lowercase letters/numbers, 3–32, no spaces. The name is unique across all businesses (e.g. asha.duka1). One business can have an admin and many users of the same role, each with their own username." },
  "Ruhusu kuingia kwa Staff PIN": { sw: "Ruhusu kuingia kwa Staff PIN", en: "Allow Staff PIN sign-in" },
  "Acha wazi ili kubakiza PIN iliyopo. Weka PIN mpya ili kuibadilisha.": { sw: "Acha wazi ili kubakiza PIN iliyopo. Weka PIN mpya ili kuibadilisha.", en: "Leave blank to keep the existing PIN. Enter a new PIN to change it." },
  "PIN haitahifadhiwa kama maandishi ya kawaida.": { sw: "PIN haitahifadhiwa kama maandishi ya kawaida.", en: "The PIN will not be saved as plain text." },
  "Idara anazoweza kufanyia kazi": { sw: "Idara anazoweza kufanyia kazi", en: "Departments he can work in" },
  "Huwezi kubadilisha idara za akaunti yako mwenyewe.": { sw: "Huwezi kubadilisha idara za akaunti yako mwenyewe.", en: "You cannot change the departments of your own account." },
  "Anaweza kufanya kazi kwenye kila idara na kubadilisha idara kwa kitufe cha idara juu ya skrini. Chagua hapa chini menyu (Sales, Bills n.k.) anazoruhusiwa kuona.": { sw: "Anaweza kufanya kazi kwenye kila idara na kubadilisha idara kwa kitufe cha idara juu ya skrini. Chagua hapa chini menyu (Sales, Bills n.k.) anazoruhusiwa kuona.", en: "Can work in every department and switch department with the department button at the top of the screen. Choose below the menus (Sales, Bills etc.) he is allowed to see." },
  "Anabadilisha kati ya idara hizi kwa kitufe cha idara juu ya skrini (mfano mhudumu anayeuza Bar na Jikoni). Kila wakati anaona na kuuza kwenye idara moja aliyoichagua.": { sw: "Anabadilisha kati ya idara hizi kwa kitufe cha idara juu ya skrini (mfano mhudumu anayeuza Bar na Jikoni). Kila wakati anaona na kuuza kwenye idara moja aliyoichagua.", en: "Switches between these departments with the department button at the top of the screen (for example a waiter who sells at the Bar and the Kitchen). At any time he sees and sells in the one department he has chosen." },
  "Amefungwa kwenye idara hii moja.": { sw: "Amefungwa kwenye idara hii moja.", en: "Locked to this one department." },
  "Tiki angalau idara moja, au washa 'Idara zote'.": { sw: "Tiki angalau idara moja, au washa 'Idara zote'.", en: "Tick at least one department, or turn on 'All departments'." },
  "Hakuna idara iliyotikiwa: meneja/admin tu ndio wanaoweza kuacha hivi.": { sw: "Hakuna idara iliyotikiwa: meneja/admin tu ndio wanaoweza kuacha hivi.", en: "No department is ticked: only a manager/admin may leave it like this." },
  "Super Admin ana ruhusa zote (Edit, Cancel/Delete, Print) kila wakati; hazizimwi.": { sw: "Super Admin ana ruhusa zote (Edit, Cancel/Delete, Print) kila wakati; hazizimwi.", en: "Super Admin always has all permissions (Edit, Cancel/Delete, Print); they cannot be turned off." },
  "Ruhusa za invoice (kwa mtumiaji huyu pekee)": { sw: "Ruhusa za invoice (kwa mtumiaji huyu pekee)", en: "Invoice permissions (for this user only)" },
  "Unaweza kutoa tu ruhusa ulizonazo wewe mwenyewe. Zinaongezwa juu ya ruhusa za role yake.": { sw: "Unaweza kutoa tu ruhusa ulizonazo wewe mwenyewe. Zinaongezwa juu ya ruhusa za role yake.", en: "You can only grant permissions that you have yourself. They are added on top of his role's permissions." },
  "Ruhusa za kawaida za kazi zinadhibitiwa kupitia Role Management; hapa unaweza kuongeza ruhusa za invoice kwa mtu mmoja, na kuchagua sidebar.": { sw: "Ruhusa za kawaida za kazi zinadhibitiwa kupitia Role Management; hapa unaweza kuongeza ruhusa za invoice kwa mtu mmoja, na kuchagua sidebar.", en: "Normal work permissions are controlled through Role Management; here you can add invoice permissions for one person, and choose the sidebar." },
  "Chagua idara za mtumiaji huyu (tiki moja au zaidi) au washa 'Idara zote'.": { sw: "Chagua idara za mtumiaji huyu (tiki moja au zaidi) au washa 'Idara zote'.", en: "Choose this user's departments (tick one or more) or turn on 'All departments'." },
